import { Diagram } from "#core/scripts/external/TypeScript-Voronoi-master/src/diagram.js";

import { MapSize, ParameterSpec, RuleConfigType, RuleConfigValueRecord } from "#base/scripts/voronoi-types.js";

import { kdTree, WrappedKdTree } from "../kd-tree.js";
import { LandmassRegion, PlateRegion } from "../voronoi-region.js";
import { Aabb2, RegionCell, RegionCellPosGetter, VoronoiUtils, WrapDistOptions, WrapType } from "../voronoi-utils.js";
import { Rule } from "../voronoi_rules/rules-base.js";

export enum GeneratorType {
	Continent,
}

export type MapGeneratorConstructor = new () => MapGenerator;

export interface RuleSetting {
	className: string;
	isActive: boolean;
	weight: number;
	record: object;
}

// Helper types for rule schema
export type RulesSchema<T extends string> = Record<
	T,
	Record<string, Partial<RuleConfigType> & Pick<RuleConfigType, "className">>
>;

export const ruleDefaults = {
	weight: 1.0,
	isActive: true,
};

export function resolveRuleConfig(cfg: RulesSchema<string>): RuleConfigValueRecord {
	const obj: RuleConfigValueRecord = {};
	for (const [ruleCategory, rules] of Object.entries(cfg)) {
		obj[ruleCategory] = {};
		for (const [ruleName, ruleSettings] of Object.entries(rules)) {
			obj[ruleCategory][ruleName] = {
				...ruleDefaults,
				...ruleSettings,
				config: { ...(ruleSettings.config ?? {}) }, // avoid shared object.
			};
		}
	}
	return obj;
}

export type GeneratorSchemaGroupChildren =
	| { type: "configs"; data: GeneratorSchema }
	| { type: "rules"; data: [Rule, RuleSetting][] };

export abstract class GeneratorSchemaGroup {
	groupLabel = "";
	childCount?: number; // define this to allow this group to contain arrays of settings.
	children: GeneratorSchemaGroupChildren = { type: "configs", data: {} };
}

export type GeneratorSchema = Record<string, ParameterSpec | GeneratorSchemaGroup>;

export type GeneratorSettingGroup = Record<string, number | boolean>;

export interface GeneratorSettingRecord {
	[key: string]:
		| number
		| boolean
		| GeneratorSettingRecord
		| GeneratorSettingRecord[]
		| GeneratorSettingGroup
		| GeneratorSettingGroup[];
}

export abstract class MapGenerator {
	protected m_generatorSettings: GeneratorSettingRecord = {};
	protected m_regionCells: RegionCell[] = [];
	protected m_diagram!: Diagram; // initialized in init()
	protected m_worldDims: float2 = { x: 0, y: 0 }; // World size accounting for sizes of hexes
	protected m_hexDims: float2 = { x: 0, y: 0 }; // Actual number of hexes in x/y.
	protected m_mapSizeType: MapSize = MapSize.Standard;
	protected m_wrap: WrapType = WrapType.None;
	protected m_kdTree: kdTree<RegionCell> = new kdTree<RegionCell>(RegionCellPosGetter); // initialized in init()
	protected m_wrapDistOpts: WrapDistOptions = { wrap: WrapType.None };

	abstract getType(): GeneratorType;
	abstract getRules(): Readonly<Record<string, Record<string, Rule>>>;
	abstract getLandmasses(): readonly LandmassRegion[];
	abstract getPlates(): readonly PlateRegion[];
	abstract simulate(): void;
	abstract getSchema(): GeneratorSchema;

	init(worldDims: float2, diagram: Diagram, hexDims: float2, wrap: WrapType = WrapType.None) {
		this.m_diagram = diagram;
		this.m_worldDims = worldDims;
		this.m_hexDims = hexDims;
		this.m_mapSizeType = VoronoiUtils.getMapSizeForDims(hexDims);
		this.m_wrap = wrap;
		this.m_wrapDistOpts = { wrap: wrap, width: worldDims.x, height: worldDims.y };

		this.m_regionCells = diagram.cells.map((cell, index) => {
			const area: number = VoronoiUtils.calculateCellArea(cell);
			const regionCell: RegionCell = new RegionCell(cell, index, area);
			return regionCell;
		});

		if (wrap == WrapType.WrapX) {
			const bounds: Aabb2 = new Aabb2({ x: 0, y: 0 }, worldDims);
			this.m_kdTree = new WrappedKdTree<RegionCell>(RegionCellPosGetter, bounds, wrap);
		}
		this.m_kdTree.build(this.m_regionCells);
	}

	public logSettings() {
		console.log(
			`generator ${this.getType()} for map size (x: ${this.m_hexDims.x}, y: ${this.m_hexDims.y}) [${this.m_mapSizeType}] initialized with settings:`,
		);

		const logObject = (obj: any, indent: string, lastKey = "") => {
			if (obj === null) {
				console.log(indent + "null");
			} else if (Array.isArray(obj)) {
				console.log(indent + lastKey + ": [");
				for (let i = 0; i < obj.length; ++i) {
					logObject(obj[i], indent + "  ", i.toString());
				}
				console.log(indent + "]");
			} else if (typeof obj === "object") {
				if (lastKey != "") {
					console.log(indent + lastKey + ": ");
				}
				for (const [key, value] of Object.entries(obj)) {
					if (key[0] === "_") continue;
					logObject(value, indent + "  ", key);
				}
			} // simple type
			else {
				console.log(indent + lastKey + ": " + obj);
			}
		};

		logObject(this.m_generatorSettings, "  ");

		console.log(`Rules:`);
		const ruleSections = this.getRules();
		for (const [ruleSection, rules] of Object.entries(ruleSections)) {
			console.log(`  ${ruleSection}:`);
			for (const [ruleName, rule] of Object.entries(rules)) {
				console.log(`    ${ruleName}: active: ${rule.isActive}, weight: ${rule.weight}`);
				for (const [key, value] of Object.entries(rule.configValues)) {
					logObject(value, "      ", key);
				}
			}
		}
	}

	static buildDefaultSettings(nodes: GeneratorSchema) {
		const out: GeneratorSettingRecord = {};
		for (const [key, node] of Object.entries(nodes)) {
			if ("children" in node) {
				// GeneratorSettingsConfigGroup
				if (node.children.type === "configs") {
					// skip rules in the config, they're handled separately
					if (node.childCount && node.childCount > 0) {
						out["_defaultChild"] = this.buildDefaultSettings(node.children.data);
						const arr: GeneratorSettingRecord[] = [];
						for (let i = 0; i < node.childCount; ++i) {
							arr[i] = this.buildDefaultSettings(node.children.data);
						}
						out[key] = arr;
					} else {
						out[key] = this.buildDefaultSettings(node.children.data);
					}
				}
			} // GeneratorSettingsConfig
			else {
				out[key] = node.default;
			}
		}
		return out;
	}

	private initializeRules(settings: Record<string, Record<string, RuleConfigType>>) {
		for (const [cat, rules] of Object.entries(this.getRules())) {
			for (const [ruleName, rule] of Object.entries(rules)) {
				rule.initialize(settings[cat][ruleName]);
			}
		}
	}

	getRegionCells(): readonly RegionCell[] {
		return this.m_regionCells;
	}
	getPlateCells(): readonly RegionCell[] {
		// Override for custom plate diagrams.
		return this.m_regionCells;
	}
	getKdTree(): Readonly<kdTree<RegionCell>> {
		return this.m_kdTree;
	}

	getSettings(): GeneratorSettingRecord {
		return this.m_generatorSettings;
	}
	setSettings(generatorSettings: GeneratorSettingRecord) {
		this.m_generatorSettings = generatorSettings;
	}

	getDiagram(): Diagram {
		return this.m_diagram;
	}
	getPlatesDiagram(): Diagram {
		// Override for custom plate diagrams.
		return this.m_diagram;
	}
}
